import {canonical} from '/private/tmp/loom-jev-large-20261001/eval.mjs';
// Experimental pure proposal policy only. No DB, scheduler, ACK or queue ownership.
export function propose(c,answers){
 const f=c.facts??{};const out=(mode,recipients=[])=>({messageId:c.id,mode,recipients});
 if(f.archived||f.alreadyDecided||(f.eventType&&f.eventType!=='message.posted'))return out('skip');
 if(f.authorKind==='human'||f.roomKind==='private'||f.explicitObligation)return out('existing-owner');
 const eligible=f.eligibleIds??c.state.members.filter(m=>m.id!==c.state.author.id).map(m=>m.id);
 const ids=label=>label==='both'?['B','C']:['B','C'].includes(label)?[label]:[];
 const fixed=canonical(c.state);if(fixed!=='none')return out('canonical',ids(fixed).filter(id=>eligible.includes(id)));
 const a=answers?.speech,b=answers?.recipient;
 if(!a||!b||a.choice!=='request'||![a.confidence,b.confidence].every(n=>Number.isFinite(n)&&n>=.9&&n<=1))return out('abstain');
 const selected=ids(b.choice);if(!selected.length||selected.some(id=>!eligible.includes(id)))return out('abstain');
 return out('semantic-proposal',selected);
}
export function canApply(p,current){return p.recipients.length>0&&p.messageId===current.messageId&&p.snapshot===current.snapshot&&!current.applied&&current.actorActive&&current.roomKind==='channel'&&p.recipients.every(id=>current.eligibleIds.includes(id));}

