import test from 'node:test';import assert from 'node:assert/strict';
import {propose,canApply} from './policy.mjs';
const c={id:'x',state:{author:{id:'A',handle:'A'},members:[{id:'B',handle:'B'},{id:'C',handle:'C'}],message:'请B检查'}};
const answer={speech:{choice:'request',confidence:.98},recipient:{choice:'B',confidence:.98}};
test('semantic agreement produces a proposal only',()=>assert.deepEqual(propose(c,answer).recipients,['B']));
test('explicit route is retained even when model vetoes',()=>assert.deepEqual(propose({...c,state:{...c.state,message:'@C 请检查'}},{speech:{choice:'no_request',confidence:1},recipient:{choice:'B',confidence:1}}).recipients,['C']));
test('Human public and private routing remains existing owner',()=>{for(const f of [{authorKind:'human'},{roomKind:'private'}])assert.equal(propose({...c,facts:f},answer).mode,'existing-owner')});
test('ineligible or removed recipients cannot be proposed',()=>assert.deepEqual(propose({...c,facts:{eligibleIds:['C']}},answer).recipients,[]));
test('not a message, archived or already decided needs no model',()=>{for(const f of [{eventType:'task.completed'},{archived:true},{alreadyDecided:true}])assert.equal(propose({...c,facts:f},answer).mode,'skip')});
test('business obligation not cancelled by classifier',()=>assert.equal(propose({...c,facts:{explicitObligation:true}},null).mode,'existing-owner'));
test('missing/error/low confidence/divergent type means abstain',()=>{for(const a of [null,{...answer,speech:{choice:'no_request',confidence:1}},{...answer,speech:{choice:'unclear',confidence:1}},{...answer,recipient:{choice:'B',confidence:.89}},{...answer,speech:{choice:'request',confidence:.89}}])assert.deepEqual(propose(c,a).recipients,[])});
test('human-only speech cannot trigger dispatch',()=>assert.deepEqual(propose(c,{...answer,speech:{choice:'human_only',confidence:.94}}).recipients,[]));
test('stale decision, duplicate, removed actor, private target fail apply check',()=>{const p=propose(c,answer);const current={messageId:'x',snapshot:'v1',eligibleIds:['B','C'],actorActive:true,roomKind:'channel',applied:false};assert.equal(canApply({...p,snapshot:'v1'},current),true);for(const change of [{snapshot:'v2'},{applied:true},{eligibleIds:[]},{actorActive:false},{roomKind:'private'}])assert.equal(canApply({...p,snapshot:'v1'},{...current,...change}),false)});
test('busy recipient is not removed; existing lane queues it',()=>assert.deepEqual(propose({...c,facts:{busyIds:['B']}},answer).recipients,['B']));

