import {readFileSync,writeFileSync} from 'node:fs';
import {canonical,metrics} from '/private/tmp/loom-jev-large-20261001/eval.mjs';
const root='/private/tmp/loom-jev-hybrid-20261001';const cases=JSON.parse(readFileSync(root+'/cases.json')).filter(c=>c.split==='regression-known');const results=JSON.parse(readFileSync(root+'/results.json'));
const grid=[];
for(const speech of [0,.3,.5,.7,.9])for(const recipient of [.7,.8,.85,.9,.95]){
 const rows=cases.map(c=>{const a=results.find(r=>r.id===c.id).answers;const fixed=canonical(c.state);const actual=fixed!=='none'?fixed:a.speech.choice==='request'&&a.speech.confidence>=speech&&a.recipient.confidence>=recipient&&['B','C','both'].includes(a.recipient.choice)?a.recipient.choice:'none';return{expected:c.expected,actual};});grid.push({speech,recipient,...metrics(rows)});
}
// Predeclared selection rule: zero wrong wakes on calibration, then highest recall;
// if ties pick highest speech and recipient confidence thresholds. All known data, no validation claim.
const eligible=grid.filter(g=>g.wrongWakes===0).sort((a,b)=>b.correctActionableRecall-a.correctActionableRecall||b.speech-a.speech||b.recipient-a.recipient);
const chosen=eligible[0];const plan={kind:'Post-hoc calibration on known P81/P82 regression only, not validation',grid,chosen,selectionRule:'zero wrong wakes, maximum recall, highest thresholds as tie-break; unchanged speech/request semantics',confirmation:{n:80,source:'Independent Codex low generates cases without any Jev answers or threshold disclosure',gate:{wrongWakes:0,correctActionableRecallAtLeast:.8},maxJevCalls:80,retry:0,model:'jev-1.13.0'},limitations:'Threshold search uses 240 correlated examples in 60 already-known families. A fresh challenge set is required. Do not treat calibration as deployment proof.'};writeFileSync(root+'/calibration.json',JSON.stringify(plan,null,2));console.log(JSON.stringify({chosen,top:eligible.slice(0,5)},null,2));

