import {readFileSync,writeFileSync} from 'node:fs';
import {canonical,decision,metrics} from '/private/tmp/loom-jev-large-20261001/eval.mjs';
import {propose} from './policy.mjs';
const root='/private/tmp/loom-jev-hybrid-20261001',read=n=>JSON.parse(readFileSync(root+'/'+n));
const cases=read('cases.json'),results=read('results.json');
const label=ids=>ids.length===2?'both':ids[0]??'none';
const rows=cases.map(c=>{const r=results.find(r=>r.id===c.id);return {...c,result:r,canonical:canonical(c.state),raw:r?.answers?.legacy?.choice??'missing',single:decision(c.state,r?.answers?.legacy??null),hybrid:label(propose(c,r?.answers).recipients)}});
const summary={calls:results.length,errors:results.filter(r=>r.error).length,input:results.reduce((s,r)=>s+(r.usage?.input_tokens??0),0),output:results.reduce((s,r)=>s+(r.usage?.output_tokens??0),0),splits:{}};
const t=results.map(r=>r.ms).sort((a,b)=>a-b);summary.latency={p50:t[Math.ceil(t.length*.5)-1],p95:t[Math.ceil(t.length*.95)-1],max:t.at(-1)};summary.estimatedUSD=summary.input*.042/1e6;
for(const split of ['regression-known','new-frozen']){const selected=rows.filter(r=>r.split===split);summary.splits[split]=Object.fromEntries(['canonical','raw','single','hybrid'].map(arm=>[arm,metrics(selected.map(r=>({expected:r.expected,actual:r[arm]})))]));}
summary.hybridWrong=rows.filter(r=>['B','C','both'].includes(r.hybrid)&&r.hybrid!==r.expected).map(r=>({id:r.id,expected:r.expected,actual:r.hybrid,message:r.state.message,answers:r.result.answers}));
summary.newMisses=rows.filter(r=>r.split==='new-frozen'&&['B','C','both'].includes(r.expected)&&r.hybrid!==r.expected).map(r=>({id:r.id,expected:r.expected,actual:r.hybrid,message:r.state.message,answers:r.result.answers}));
summary.pass=summary.errors===0&&summary.hybridWrong.length===0&&summary.splits['new-frozen'].hybrid.correctActionableRecall>=.8;
summary.blindAnnotation={provider:'codex',model:'gpt-6-luna',effort:'low',count:64,disagreements:read('blind-review.json').disagreements,metrics:read('annotation.json').rounds[0].metrics};
writeFileSync(root+'/summary.json',JSON.stringify(summary,null,2));console.log(JSON.stringify(summary,null,2));
